// Crux's task reminder as a panel above the prompt.
//
// The data and the text are still generated by the kernel (lib/task-sync.mjs)
// and the SessionStart shell hook, which is what Codex, the web and the phone
// see. This mod only changes how it is shown in Claude Code: it tells the hook
// through CRUX_REMINDER_UI not to print the text and draws the same content as
// a panel, with a numeric shortcut to resume each task.
import { atom, read, update } from 'claude-code'

const title = atom({ plugin: 'crux', key: 'title' }, '')
const tasks = atom({ plugin: 'crux', key: 'tasks' }, [])
const more = atom({ plugin: 'crux', key: 'more' }, 0)
const hidden = atom({ plugin: 'crux', key: 'hidden' }, false)
const currentTask = atom({ plugin: 'crux', key: 'currentTask' }, '')

// The plugin lives in <kernel>/adapters/claude/plugin.
const kernelOf = (root: string) => root.replace(/\/adapters\/claude\/plugin\/?$/, '')

async function load($) {
  const cwd = await $.session.cwd()
  const { exitCode, stdout } = await $.process.run(
    ['node', kernelOf($.plugin.root) + '/lib/task-sync.mjs', 'remind', '--cwd', cwd],
    { timeoutMs: 20000 },
  )
  const data = exitCode === 0 && stdout.trim() ? JSON.parse(stdout) : null
  await update($, title, () => data?.title ?? '')
  await update($, tasks, () => data?.tasks ?? [])
  await update($, more, () => data?.more ?? 0)
  await update($, hidden, () => false)
}

// The task of the workspace the session is in, found the same way as the
// task-context hook: common.sh finds it and task.mjs summarises it.
const SUMMARY = `
  source "$1/lib/common.sh"
  f="$(task_file_for_path "\${CRUX_REGISTRY:-$HOME/.crux/workspaces.json}" "$2")" || exit 0
  node "$1/lib/task.mjs" summary --file "$f" --json`

async function taskStatus($) {
  const cwd = await $.session.cwd()
  const git = await $.process.run(['git', '-C', cwd, 'rev-parse', '--show-toplevel'])
  const root = git.exitCode === 0 ? git.stdout.trim() : ''
  let label = ''
  if (root.includes('-ws-')) {
    const { exitCode, stdout } = await $.process.run(
      ['bash', '-c', SUMMARY, 'crux', kernelOf($.plugin.root), root],
      { timeoutMs: 10000 },
    )
    if (exitCode === 0 && stdout.trim()) {
      const t = JSON.parse(stdout)
      label = [t.task, t.steps ? 'steps ' + t.steps : t.status].filter(Boolean).join(' · ')
    }
  }
  await update($, currentTask, () => label)
}

export function register(on) {
  // The status line is refreshed when each turn ends: that is when the agent
  // may have ticked steps or changed the next one with crux task.
  on('turn.complete', async ($, e, next) => {
    const r = await next(e)
    await taskStatus($)
    return r
  })

  // Runs before the settings.json hooks for the same event: the variable is
  // already set when Crux's hook decides whether to print the text.
  on('classic.SessionStart', async ($, e, next) => {
    await $.env.set('CRUX_REMINDER_UI', 'panel')
    const result = await next(e)
    // After compacting the session is still mid-work: the hook is silent and so is the panel.
    if (e.source !== 'compact') await load($)
    await taskStatus($)
    return result
  })

  // As soon as the person types, the reminder has done its job.
  on('prompt.submit', async ($, e, next) => {
    await update($, hidden, () => true)
    return next(e)
  })

  // The workspace's task, among the mode labels in the prompt footer:
  // discreet and always in view, without going through the conversation.
  on('ui.render', { component: 'SessionMode' }, async ($, e, next) => {
    const label = await read($, currentTask)
    if (!label) return next(e)
    return next({ ...e, props: { ...e.props, modes: [...e.props.modes, '▸ ' + label] } })
  })

  // A task waiting on another person is not pending work: it says who it
  // waits on and since when, and warns when a nudge is due.
  const waitingLabel = (w) => {
    const age = w.days == null ? '' : w.days === 0 ? 'today' : w.days === 1 ? 'yesterday' : w.days + ' days ago'
    return '· waiting on ' + w.on + (age ? ', ' + age : '') + (w.nudge ? ' · worth a nudge' : '')
  }

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const list = await read($, tasks)
    if ((await read($, hidden)) || list.length === 0) return next(e)
    const remaining = await read($, more)
    const { Box, Text, Button } = $.ui.resolve(e)

    const row = (t, i) =>
      Box({
        key: 'task-' + t.task,
        flexDirection: 'column',
        children: [
          Box({
            flexDirection: 'row',
            columnGap: 1,
            children: [
              Button({
                key: 'resume-' + t.task,
                label: t.task,
                hotkey: String(i + 1),
                plain: true,
                onPress: async () => {
                  await update($, hidden, () => true)
                  await $.prompt.submit({ text: `Let's resume the task ${t.task}.`, asUser: true })
                },
              }),
              ...(t.waiting
                ? [Text({ color: t.waiting.nudge ? 'warning' : undefined, dimColor: !t.waiting.nudge, children: [waitingLabel(t.waiting)] })]
                : [
                    Text({ dimColor: true, children: ['· ' + t.when + (t.status === 'open' ? '' : ' · ' + t.status)] }),
                    ...(t.here ? [] : [Text({ color: 'warning', children: ['· no workspace here'] })]),
                  ]),
            ],
          }),
          ...(t.next
            ? [Text({ dimColor: true, wrap: 'truncate-end', children: ['   ' + t.next] })]
            : []),
        ],
      })

    return Box({
      flexDirection: 'column',
      borderStyle: 'round',
      paddingX: 1,
      children: [
        Box({
          flexDirection: 'row',
          columnGap: 1,
          children: [
            Text({ bold: true, children: [(await read($, title)) || 'Open tasks'] }),
            Text({ dimColor: true, children: ['· press the number to resume one'] }),
          ],
        }),
        ...list.map(row),
        ...(remaining > 0 ? [Text({ dimColor: true, children: [`and ${remaining} more: crux status`] })] : []),
        Box({
          flexDirection: 'row',
          children: [
            Button({
              key: 'hide',
              label: 'Hide',
              plain: true,
              dimColor: true,
              onPress: () => update($, hidden, () => true),
            }),
          ],
        }),
      ],
    })
  })
}
